Declare @StartDate DATETIME = @StartDate_Adhoc;
Declare @EndDate DATETIME = @EndDate_Adhoc;

SET @StartDate = Case When @StartDate  = '1/1/1900' Then DATEADD(year, -3, DATEADD(month, DATEDIFF(month, -1, getdate()) - 1, 0)) Else @StartDate END
SET @EndDate  = Case When @EndDate  = '1/1/1900' Then DATEADD("d", -DAY(GETDATE()), DATEADD("m", 0, GETDATE()))
Else @EndDate END

select @StartDate,@EndDate
